<div class="box box-warning"><div class="box-header"><h3 class="box-title">Reportes de Encomiendas</h3></div><div class="box-body"><form class="form-inline" method="get"><label>Desde</label> <input type="date" name="desde" value="<?php echo $desde; ?>" class="form-control"> <label>Hasta</label> <input type="date" name="hasta" value="<?php echo $hasta; ?>" class="form-control"> <button class="btn btn-primary"><i class="fa fa-search"></i> Buscar</button></form><hr><div class="row"><div class="col-md-3"><div class="small-box bg-aqua"><div class="inner"><h3><?php echo (int)$resumen['cantidad']; ?></h3><p>Encomiendas</p></div></div></div><div class="col-md-3"><div class="small-box bg-green"><div class="inner"><h3><?php echo number_format($resumen['total'],2); ?></h3><p>Total Bs</p></div></div></div><div class="col-md-3"><div class="small-box bg-yellow"><div class="inner"><h3><?php echo (int)$resumen['pendientes']; ?></h3><p>Pendientes</p></div></div></div><div class="col-md-3"><div class="small-box bg-red"><div class="inner"><h3><?php echo number_format($resumen['saldo'],2); ?></h3><p>Saldo</p></div></div></div></div><table class="table table-bordered table-striped"><thead><tr><th>Guía</th><th>Fecha</th><th>Cliente</th><th>Destino</th><th>Total</th><th>Saldo</th><th>Estado</th></tr></thead><tbody><?php foreach($reporte as $r){ ?><tr><td><?php echo $r['encomienda_guia']; ?></td><td><?php echo $r['encomienda_fecha']; ?></td><td><?php echo $r['encomienda_remitentenombre']; ?></td><td><?php echo $r['destino_nombre']; ?></td><td><?php echo number_format($r['encomienda_total'],2); ?></td><td><?php echo number_format($r['encomienda_saldo'],2); ?></td><td><?php echo $r['encomiendaestado_nombre']; ?></td></tr><?php } ?></tbody></table></div></div>
